#include "../engine/native/smoke/particle_source.hpp"
#include "../engine/native/smoke/gpu.hpp"
#include "../third_party/json.hpp"
#include "d3d12_test_rig.hpp"
#include <cmath>
#include <limits>
namespace s=engine::smoke;namespace e=engine::effects;using gpu_test::Rig;
namespace {
unsigned checks=0,groups=0;std::uint64_t comparisons=0,immutableComparisons=0;auto cases=nlohmann::json::array();
void require(bool ok,const char* why){++checks;if(!ok)throw std::runtime_error(why);}
template<class F>void throws(F fn,const char* why){bool caught=false;try{fn();}catch(const std::exception&){caught=true;}require(caught,why);}
s::Spec spec(){s::Spec p;p.dimensions={4,4,4};p.originMetres={10,-2,3};p.cellMetres=.5f;p.maxSpeed=1;p.macCormack=false;p.pressureIterations=4;p.densityDecay=p.cooling=p.fuelDecay=p.burnRate=p.buoyancy=p.smokeWeight=p.vorticity=0;return p;}
e::Emitter emitter(bool local){e::Emitter em;em.id=local?"local":"world";em.position={.25f,.25f,.25f};em.lifeMin=em.lifeMax=1000;em.localSpace=local;em.modules.push_back({});e::Renderer r;r.type="sprite";r.texture="test.png";em.renderers.push_back(r);return em;}
std::vector<float> copy(Rig& rig,ID3D12Resource* source,unsigned count){gpu_test::Com<ID3D12Resource> target;const std::size_t bytes=std::size_t(count)*4;gpu_test::makeBuffer(rig.device.p,target,bytes,D3D12_HEAP_TYPE_READBACK,D3D12_RESOURCE_STATE_COPY_DEST);gpu_test::transition(rig.commands.p,source,D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE,D3D12_RESOURCE_STATE_COPY_SOURCE);rig.commands.p->CopyBufferRegion(target.p,0,source,0,bytes);gpu_test::transition(rig.commands.p,source,D3D12_RESOURCE_STATE_COPY_SOURCE,D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE);rig.submit();void* mapped=nullptr;D3D12_RANGE range{0,bytes},none{0,0};gpu_test::hr(target.p->Map(0,&range,&mapped),"Map smoke particle test result");std::vector<float> values(count);std::memcpy(values.data(),mapped,bytes);target.p->Unmap(0,&none);return values;}
std::vector<float> rates(Rig& rig,const std::shared_ptr<s::GpuSmokeRateView>& view){rig.begin();require(view->markUsed(rig.ticket()),"Rate test consumer fence");return copy(rig,view->bindings().rates,view->bindings().layout.scalarCount);}
std::array<std::uint32_t,12> diagnostics(Rig& rig,const std::shared_ptr<s::GpuSmokeRateView>& view){rig.begin();require(view->markUsed(rig.ticket()),"Diagnostic test consumer fence");const auto raw=copy(rig,view->bindings().diagnostics,12);std::array<std::uint32_t,12> out{};std::memcpy(out.data(),raw.data(),48);return out;}
std::vector<float> state(Rig& rig,s::GpuSmokeFireSolver& solver){rig.begin();std::string error;require(solver.prepareRead(rig.commands.p,rig.ticket(),error),error.c_str());return copy(rig,solver.buffers().scalars,solver.buffers().layout.scalarCount);}
void compare(const std::vector<float>& gpu,const std::vector<float>& reference,float tolerance=.0001f,bool cpuReference=true){require(gpu.size()==reference.size(),"Scalar layout mismatch");for(unsigned i=0;i<gpu.size();++i){require(std::isfinite(gpu[i])&&std::abs(gpu[i]-reference[i])<tolerance,"Particle-fed smoke differs from independent CPU input reference");if(cpuReference)++comparisons;else ++immutableComparisons;}}
void finish(Rig& rig,s::GpuSmokeFireSolver& solver,s::GpuParticleSmokeSource& source){std::string error;require(solver.shutdown(error),error.c_str());source.collect();require(source.stats().allocationBytes==0&&source.stats().heldInputReferences==0,"Completed unreferenced source resources leaked");require(source.shutdown(error),error.c_str());require(rig.fence.p->GetCompletedValue()>=rig.submitted,"Queue not actually completed");}
void mixedSpaceHistory(Rig& rig){
    const auto p=spec();const auto l=s::layout(p);std::string error;e::GpuParticlePool local(rig.device.p,emitter(true),4),world(rig.device.p,emitter(false),4);s::GpuParticleSmokeSource source(rig.device.p,rig.fence.p,p,{{1024,1024,1024}});s::GpuSmokeFireSolver solver(rig.device.p,rig.fence.p,p);
    std::vector<s::CellInput> base(l.cells);base[0].densityRate=.25f;base[0].temperatureRate=-.5f;base[0].fuelRate=.1f;require(solver.setInputs(base,error),error.c_str());auto reference=s::initialState(p);auto expected=base;expected[0].densityRate+=3;expected[0].temperatureRate+=6;expected[0].fuelRate+=1.5f;
    rig.begin();require(local.initialize(rig.commands.p,rig.ticket(),error)&&world.initialize(rig.commands.p,rig.ticket(),error),error.c_str());require(local.step(rig.commands.p,rig.ticket(),0,2,0,1,p.originMetres,error)&&world.step(rig.commands.p,rig.ticket(),0,1,0,2,p.originMetres,error),error.c_str());
    auto first=source.produce({{&local,{128,256,64}},{&world,{128,256,64}}},rig.commands.p,rig.ticket(),0,error);require(!!first,error.c_str());require(solver.step(rig.commands.p,rig.ticket(),0,.01f,error,first),error.c_str());rig.submit();s::step(p,expected,reference,.01f);compare(state(rig,solver),reference.scalars);const auto firstRates=rates(rig,first);require(firstRates[0]==3&&firstRates[l.offsets[1]]==6&&firstRates[l.offsets[2]]==1.5f,"Mass/heat-volume units or alive list incorrect");const auto d=diagnostics(rig,first);require(d[0]==3&&d[1]==0&&d[2]==0&&d[3]==0,"Valid source diagnostics");
    const engine::Vec3 moved{10.5f,-2,3};rig.begin();require(local.step(rig.commands.p,rig.ticket(),1,0,2,1,moved,error)&&world.step(rig.commands.p,rig.ticket(),1,0,1,2,moved,error),error.c_str());auto second=source.produce({{&local,{128,256,64}},{&world,{128,256,64}}},rig.commands.p,rig.ticket(),1,error);require(!!second,error.c_str());const auto before=source.stats();require(!source.produce({{&local,{128,256,64}}},rig.commands.p,rig.ticket(),1,error)&&source.stats().dispatches==before.dispatches,"Duplicate tick recorded source work");require(solver.step(rig.commands.p,rig.ticket(),1,.01f,error,second),error.c_str());rig.submit();
    expected=base;expected[0].densityRate+=1;expected[0].temperatureRate+=2;expected[0].fuelRate+=.5f;expected[1].densityRate=2;expected[1].temperatureRate=4;expected[1].fuelRate=1;s::step(p,expected,reference,.01f);compare(state(rig,solver),reference.scalars);const auto movedRates=rates(rig,second);require(movedRates[0]==1&&movedRates[1]==2,"Local/world source transforms were conflated");compare(rates(rig,first),firstRates,1e-8f,false);
    rig.begin();const auto calls=solver.stats().dispatches;require(!solver.step(rig.commands.p,rig.ticket(),2,.01f,error,first)&&solver.stats().dispatches==calls,"Stale source tick was replayed");require(local.clear(rig.commands.p,rig.ticket(),error)&&world.clear(rig.commands.p,rig.ticket(),error),error.c_str());auto zero=source.produce({},rig.commands.p,rig.ticket(),2,error);require(!!zero&&solver.step(rig.commands.p,rig.ticket(),2,.01f,error,zero),error.c_str());rig.submit();s::step(p,base,reference,.01f);compare(state(rig,solver),reference.scalars);for(auto rate:rates(rig,zero))require(rate==0,"Empty full source set retained old injection");require(reference.scalars[0]>.04f,"Empty source reset historical smoke");
    cases.push_back({{"case","mixed-local-world-history"},{"alive",3},{"sourceRates",{3,6,1.5}},{"ticks",3},{"oldViewsImmutable",true},{"zeroSourcePreservesHistory",true}});first.reset();second.reset();zero.reset();require(local.shutdown(rig.fence.p->GetCompletedValue(),error)&&world.shutdown(rig.fence.p->GetCompletedValue(),error),error.c_str());finish(rig,solver,source);++groups;
}
void rejectionAndLoss(Rig& rig){
    auto p=spec();std::string error;e::GpuParticlePool pool(rig.device.p,emitter(true),4);s::GpuParticleSmokeSource source(rig.device.p,rig.fence.p,p,{{1024,1024,1024}});
    rig.begin();require(pool.initialize(rig.commands.p,rig.ticket(),error)&&pool.step(rig.commands.p,rig.ticket(),0,2,0,1,{9.5f,-2,3},error),error.c_str());rig.submit();rig.begin();const auto unchanged=[&]{const auto st=source.stats();return st.frames==0&&st.dispatches==0&&st.allocationBytes==0&&!st.failed;};
    require(!source.produce({{&pool,{1,0,0}},{&pool,{1,0,0}}},rig.commands.p,rig.ticket(),0,error)&&unchanged(),"Duplicate pools admitted");require(!source.produce({{&pool,{UINT32_MAX,0,0}}},rig.commands.p,rig.ticket(),0,error)&&unchanged(),"Integer overflow admitted");require(!source.produce({{&pool,{40000000,0,0}}},rig.commands.p,rig.ticket(),0,error)&&unchanged(),"Unbounded per-cell physical rate admitted");require(!source.produce({{&pool,{0,0,0}}},rig.commands.p,rig.ticket(),0,error)&&unchanged(),"Zero batch silently processed");
    auto only=p;only.channels=s::Density;s::GpuParticleSmokeSource density(rig.device.p,rig.fence.p,only);require(!density.produce({{&pool,{1,1,0}}},rig.commands.p,rig.ticket(),0,error)&&density.stats().allocationBytes==0,"Disabled temperature source admitted");s::GpuParticleSmokeSource tiny(rig.device.p,rig.fence.p,p,{}, {1,1,1,4});require(!tiny.produce({},rig.commands.p,rig.ticket(),0,error)&&tiny.stats().dispatches==0,"Aligned byte budget checked after dispatch");
    auto outside=source.produce({{&pool,{128,256,64}}},rig.commands.p,rig.ticket(),0,error);require(!!outside,error.c_str());rig.submit();const auto d=diagnostics(rig,outside);require(d[0]==0&&d[1]==2&&d[2]==0&&d[4]==256&&d[5]==512&&d[6]==128,"Outside-grid loss accounting incorrect");for(auto value:rates(rig,outside))require(value==0,"Negative coordinates clamped into grid");
    s::GpuSmokeFireSolver solver(rig.device.p,rig.fence.p,p);auto different=p;different.originMetres.x+=1;s::GpuParticleSmokeSource foreignGrid(rig.device.p,rig.fence.p,different);gpu_test::Com<ID3D12Fence> otherFence;gpu_test::hr(rig.device.p->CreateFence(0,D3D12_FENCE_FLAG_NONE,IID_PPV_ARGS(otherFence.out())),"Create foreign timeline");s::GpuParticleSmokeSource foreignTimeline(rig.device.p,otherFence.p,p);
    rig.begin();auto wrongGrid=foreignGrid.produce({},rig.commands.p,rig.ticket(),0,error);auto wrongTimeline=foreignTimeline.produce({},rig.commands.p,rig.ticket(),0,error);require(!!wrongGrid&&!!wrongTimeline,error.c_str());require(!solver.step(rig.commands.p,rig.ticket(),0,.01f,error,wrongGrid)&&!solver.step(rig.commands.p,rig.ticket(),0,.01f,error,wrongTimeline)&&solver.stats().dispatches==0&&solver.stats().inputSnapshots==0,"Foreign grid/timeline rejected too late");rig.submit();gpu_test::hr(otherFence.p->Signal(rig.submitted),"Complete foreign test timeline after queue");
    wrongGrid.reset();wrongTimeline.reset();outside.reset();require(foreignGrid.shutdown(error)&&foreignTimeline.shutdown(error)&&density.shutdown(error)&&tiny.shutdown(error),error.c_str());require(pool.shutdown(rig.fence.p->GetCompletedValue(),error),error.c_str());finish(rig,solver,source);cases.push_back({{"case","preflight-rejections-and-outside-loss"},{"outsideParticles",2},{"outsideQuanta",{256,512,128}},{"rejectedBeforeWork",true}});++groups;
}
void queueLifetimes(Rig& rig){
    auto p=spec();p.channels=s::Density;std::string error;e::GpuParticlePool pool(rig.device.p,emitter(true),4);s::GpuParticleSmokeSource source(rig.device.p,rig.fence.p,p,{{1024,1024,1024}},{4*1024*1024,2,2,4});s::GpuSmokeFireSolver solver(rig.device.p,rig.fence.p,p,{16*1024*1024,2,4096});
    gpu_test::Com<ID3D12Fence> gate;gpu_test::hr(rig.device.p->CreateFence(0,D3D12_FENCE_FLAG_NONE,IID_PPV_ARGS(gate.out())),"Create source lifetime queue gate");struct Release{ID3D12Fence* fence;~Release(){fence->Signal(1);}} release{gate.p};gpu_test::hr(rig.queue.p->Wait(gate.p,1),"Gate source lifetime queue");
    rig.begin();bool ok=pool.initialize(rig.commands.p,rig.ticket(),error)&&pool.step(rig.commands.p,rig.ticket(),0,1,0,1,p.originMetres,error);auto a=source.produce({{&pool,{128,0,0}}},rig.commands.p,rig.ticket(),0,error);ok=ok&&bool(a)&&solver.step(rig.commands.p,rig.ticket(),0,.01f,error,a);auto b=source.produce({{&pool,{256,0,0}}},rig.commands.p,rig.ticket(),1,error);ok=ok&&bool(b)&&solver.step(rig.commands.p,rig.ticket(),1,.01f,error,b);const auto calls=source.stats().dispatches;const bool full=!source.produce({},rig.commands.p,rig.ticket(),2,error)&&source.stats().dispatches==calls;rig.submit(false);
    const auto blocked=source.stats();const bool held=blocked.heldInputReferences==8&&solver.stats().particleRateSnapshots==2&&!source.shutdown(error)&&!solver.shutdown(error);const bool poolRejected=!pool.shutdown(rig.fence.p->GetCompletedValue(),error);gpu_test::hr(gate.p->Signal(1),"Release source lifetime queue");rig.wait();require(ok&&full&&held&&poolRejected,"Queue-gated resource lifetime or frame bound failed");require(pool.shutdown(rig.fence.p->GetCompletedValue(),error),error.c_str());source.collect();solver.collect();require(source.stats().heldInputReferences==0&&solver.stats().particleRateSnapshots==0,"Completed producer inputs or consumer references not reclaimed");const auto savedA=rates(rig,a),savedB=rates(rig,b);require(savedA[0]==1&&savedB[0]==2,"Same-fence rate snapshots overwrote each other");const auto values=state(rig,solver);require(std::abs(values[0]-.03f)<1e-6f,"Same-fence ticks lost source contributions");require(!source.shutdown(error),"Externally held rate views were reclaimed");a.reset();b.reset();finish(rig,solver,source);cases.push_back({{"case","actual-queue-lifetimes"},{"heldInputReferences",blocked.heldInputReferences},{"consumerRateSnapshots",2},{"sameFenceTicks",2},{"retiredWithoutReadback",true}});++groups;
}
void substeps(Rig& rig){
    auto p=spec();p.channels=s::Density;p.maxSpeed=8;std::string error;e::GpuParticlePool pool(rig.device.p,emitter(true),4);s::GpuParticleSmokeSource source(rig.device.p,rig.fence.p,p,{{1024,1024,1024}});s::GpuSmokeFireSolver solver(rig.device.p,rig.fence.p,p);require(s::substeps(p,.07f)==3,"Expected multi-substep test");rig.begin();require(pool.initialize(rig.commands.p,rig.ticket(),error)&&pool.step(rig.commands.p,rig.ticket(),0,1,0,1,p.originMetres,error),error.c_str());auto view=source.produce({{&pool,{128,0,0}}},rig.commands.p,rig.ticket(),0,error);require(!!view&&solver.step(rig.commands.p,rig.ticket(),0,.07f,error,view),error.c_str());rig.submit();const auto values=state(rig,solver);require(std::abs(values[0]-.07f)<1e-6f,"Source rate applied full tick dt on every substep");for(unsigned i=1;i<values.size();++i)require(values[i]==0,"Stationary particle source leaked cells");view.reset();require(pool.shutdown(rig.fence.p->GetCompletedValue(),error),error.c_str());finish(rig,solver,source);cases.push_back({{"case","substep-rate-integration"},{"substeps",3},{"dt",.07},{"density",values[0]}});++groups;
}
void delayedConsumer(Rig& rig){
    auto p=spec();p.channels=s::Density;std::string error;e::GpuParticlePool pool(rig.device.p,emitter(true),4);s::GpuParticleSmokeSource source(rig.device.p,rig.fence.p,p,{{1024,1024,1024}},{4*1024*1024,1,1,4});s::GpuSmokeFireSolver solver(rig.device.p,rig.fence.p,p);
    rig.begin();require(pool.initialize(rig.commands.p,rig.ticket(),error)&&pool.step(rig.commands.p,rig.ticket(),0,1,0,1,p.originMetres,error),error.c_str());auto view=source.produce({{&pool,{128,0,0}}},rig.commands.p,rig.ticket(),0,error);require(!!view,error.c_str());rig.submit();const auto producerFence=rig.submitted;const auto afterProducer=source.stats();require(afterProducer.heldInputReferences==0&&afterProducer.allocationBytes==131072,"Completed producer did not release accumulator/input resources independently of outputs");require(pool.shutdown(rig.fence.p->GetCompletedValue(),error),error.c_str());
    gpu_test::Com<ID3D12Fence> gate;gpu_test::hr(rig.device.p->CreateFence(0,D3D12_FENCE_FLAG_NONE,IID_PPV_ARGS(gate.out())),"Create delayed consumer gate");struct Release{ID3D12Fence* fence;~Release(){fence->Signal(1);}} release{gate.p};gpu_test::hr(rig.queue.p->Wait(gate.p,1),"Gate delayed consumer");rig.begin();const bool accepted=solver.step(rig.commands.p,rig.ticket(),0,.01f,error,view);const auto consumerFence=rig.ticket();view.reset();const auto calls=source.stats().dispatches;const bool bound=!source.produce({},rig.commands.p,rig.ticket(),1,error)&&source.stats().dispatches==calls;rig.submit(false);const bool protectedOutputs=source.stats().views==1&&source.stats().allocationBytes==131072&&solver.stats().particleRateSnapshots==1&&!source.shutdown(error)&&rig.fence.p->GetCompletedValue()==producerFence;gpu_test::hr(gate.p->Signal(1),"Release delayed consumer");rig.wait();require(accepted&&bound&&protectedOutputs&&consumerFence>producerFence,"Consumer extension failed after producer inputs had retired");solver.collect();source.collect();require(source.stats().views==0&&source.stats().allocationBytes==0,"Consumer completion did not release the final output view");const auto result=state(rig,solver);require(std::abs(result[0]-.01f)<1e-6f,"Source destroyed before delayed consumption");finish(rig,solver,source);cases.push_back({{"case","delayed-consumer-fence"},{"producerFence",producerFence},{"consumerFence",consumerFence},{"heldOutputBytes",afterProducer.allocationBytes},{"poolDestroyedBeforeConsumer",true}});++groups;
}
void partialRecordingFailure(Rig& rig){
    auto p=spec();p.channels=s::Density;std::string error;e::GpuParticlePool pool(rig.device.p,emitter(true),4);s::GpuParticleSmokeSource source(rig.device.p,rig.fence.p,p);
    rig.begin();require(pool.initialize(rig.commands.p,rig.ticket(),error)&&pool.simulate(rig.commands.p,rig.ticket(),0,p.originMetres,error),error.c_str());const bool rejected=!source.produce({{&pool,{1,0,0}}},rig.commands.p,rig.ticket(),0,error);const auto failed=source.stats();const bool retryRejected=!source.produce({},rig.commands.p,rig.ticket(),0,error)&&source.stats().dispatches==failed.dispatches;rig.submit();require(rejected&&retryRejected&&failed.failed&&failed.heldInputReferences==4&&failed.dispatches==1,"Partially recorded source work allowed replay or lost resource ownership");source.collect();require(source.stats().allocationBytes==0&&source.shutdown(error),error.c_str());require(pool.shutdown(rig.fence.p->GetCompletedValue(),error),error.c_str());cases.push_back({{"case","partial-recorder-failure"},{"dispatchesBeforeFailure",failed.dispatches},{"requiresDrainAndRecreate",true}});++groups;
}
}
int main(int argc,char** argv){try{std::string adapter;if(argc==3&&std::string(argv[1])=="--adapter")adapter=argv[2];else if(argc!=1)throw std::runtime_error("Usage: native_smoke_particles_tests [--adapter substring]");Rig rig(adapter);require(rig.debug,"D3D12 debug layer required");std::cerr<<"mixedSpaceHistory\n";mixedSpaceHistory(rig);std::cerr<<"rejectionAndLoss\n";rejectionAndLoss(rig);std::cerr<<"queueLifetimes\n";queueLifetimes(rig);std::cerr<<"substeps\n";substeps(rig);std::cerr<<"delayedConsumer\n";delayedConsumer(rig);std::cerr<<"partialRecordingFailure\n";partialRecordingFailure(rig);const auto errors=rig.debugErrors();require(errors==0,"Particle smoke debug errors");std::cout<<nlohmann::json{{"schema","nativegpu.smoke-particles-evidence/1"},{"ok",true},{"groups",groups},{"checks",checks},{"comparisons",comparisons},{"immutableSnapshotComparisons",immutableComparisons},{"adapter",rig.adapter},{"debugLayer",rig.debug},{"debugErrors",errors},{"cases",cases},{"runtimeReadback",false},{"rendererIntegrated",false},{"worldFieldIntegrated",false}}.dump()<<'\n';}catch(const std::exception& ex){std::cerr<<"Smoke particles failed after "<<checks<<" checks: "<<ex.what()<<'\n';return 1;}}
